INSERT INTO `behaviour_components` VALUES ('42cb07d2-7ab9-11f1-8dcf-4bfd1368d0d8','on_time_completion','On-Time Completion %',20.00,'Share of assigned work (flowchart, delegation, checklist) completed by its due date.','active','2026-07-08 16:09:13','2026-07-08 16:09:13'),('42cb0d68-7ab9-11f1-8dcf-4bfd1368d0d8','delay_frequency','Delay Frequency',10.00,'Inverse of how often work is completed late, regardless of by how much.','active','2026-07-08 16:09:13','2026-07-08 16:09:13'),('42cb0e08-7ab9-11f1-8dcf-4bfd1368d0d8','average_delay','Average Delay',10.00,'Inverse of the average number of days late, across delayed items only.','active','2026-07-08 16:09:13','2026-07-08 16:09:13'),('42cb0e76-7ab9-11f1-8dcf-4bfd1368d0d8','task_consistency','Task Completion Consistency',10.00,'How stable an employee\'s on-time rate has been over the last 3 months (low swings = high consistency).','active','2026-07-08 16:09:13','2026-07-08 16:09:13'),('42cb0ebc-7ab9-11f1-8dcf-4bfd1368d0d8','checklist_discipline','Checklist Discipline',10.00,'Checklist completion rate, same source as the Office Performance module.','active','2026-07-08 16:09:13','2026-07-08 16:09:13'),('42cb0f0c-7ab9-11f1-8dcf-4bfd1368d0d8','delegation_discipline','Delegation Discipline',10.00,'Delegated task on-time completion rate.','active','2026-07-08 16:09:13','2026-07-08 16:09:13'),('42cb0f52-7ab9-11f1-8dcf-4bfd1368d0d8','followup_discipline','Follow-up Discipline',10.00,'CRM follow-up on-time completion rate (merchants only - null for non-merchants).','active','2026-07-08 16:09:13','2026-07-08 16:09:13'),('42cb0f98-7ab9-11f1-8dcf-4bfd1368d0d8','crm_discipline','CRM Data Discipline',5.00,'Share of assigned CRM leads updated within the last 14 days (merchants only).','active','2026-07-08 16:09:13','2026-07-08 16:09:13'),('42cb0fe8-7ab9-11f1-8dcf-4bfd1368d0d8','attendance_impact','Attendance Impact',5.00,'Manually recorded attendance score, same manual KPI as the Scoring Engine (no time-clock system exists).','active','2026-07-08 16:09:13','2026-07-08 16:09:13'),('42cb102e-7ab9-11f1-8dcf-4bfd1368d0d8','improvement_trend','Improvement Trend',5.00,'This period\'s behaviour index versus the previous period\'s, as a bonus/penalty.','active','2026-07-08 16:09:13','2026-07-08 16:09:13'),('42cb106a-7ab9-11f1-8dcf-4bfd1368d0d8','manager_feedback','Manager Feedback',5.00,'The employee\'s manager\'s qualitative rating for this period (1-5 stars, scaled to 0-100).','active','2026-07-08 16:09:13','2026-07-08 16:09:13');
/*!40000 ALTER TABLE `behaviour_components` ENABLE KEYS */;
