INSERT INTO `fms_managers` VALUES ('7f0926a5-f41c-4c6b-8fee-4206cd1c2cab','BUYER ORDER TO CARTON ORDER',NULL,'This workflow manages the complete process from receiving a buyer\'s order to placing the carton order required for packaging. It ensures all order specifications, technical documents, material planning, approvals, production planning, and packaging requirements are completed accurately before carton procurement is initiated.',NULL,NULL,0,0,'2026-07-24 09:40:52','2026-07-25 08:16:29','[]'),('c17a021c-c3c3-42ff-8491-875c2f698cbf','FINISHED PRODUCTS TO DELIVERY',NULL,'This is a centralised workflow module designed to manage the complete export shipment lifecycle after production is completed. It streamlines coordination with shipping lines, freight forwarders, inspection agencies, banks, and buyers while ensuring timely documentation, container dispatch, compliance, payment collection, and shipment tracking. The module provides complete visibility of every export shipment, minimizes documentation errors, and ensures on-time execution of all post-production export activities.',NULL,NULL,0,0,'2026-07-25 07:05:28','2026-07-25 07:05:28',NULL),('c5830538-2b81-42ca-a41e-9e748a28c466','DELIVERY TO CLEARANCE',NULL,'Delivery to Clearance is the final stage of the export workflow, ensuring completion of all post-shipment compliance, banking, licensing, and statutory documentation. This process includes submission of export documents to the bank, tracking BRC and export incentives, maintaining EP records, monitoring export licence status, and confirming receipt of all applicable payments to complete the export transaction successfully.',NULL,NULL,0,0,'2026-07-25 08:30:19','2026-07-25 08:30:19',NULL),('e3132184-1f3d-457a-ae0b-bfcf312cc58b','SAMPLE FMS',NULL,'Sample Management FMS is a structured workflow module designed to manage the complete lifecycle of customer sample requests. It enables seamless coordination between Sales, Design, Production, Quality, and Dispatch teams by tracking every stage of the sample development process—from request initiation and design approval to manufacturing, quality inspection, dispatch, customer feedback, and final approval. The module ensures timely execution, complete traceability, improved communication, and faster sample turnaround while maintaining quality standards and customer satisfaction.',NULL,NULL,0,0,'2026-07-25 08:35:38','2026-07-25 08:35:38',NULL);
/*!40000 ALTER TABLE `fms_managers` ENABLE KEYS */;
UNLOCK TABLES;

