  `is_sequential` tinyint(1) NOT NULL DEFAULT '1',
  `sequence_order` int NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `doer_employee_ids` json DEFAULT NULL,
  `depends_on_step_ids` json DEFAULT (_utf8mb4'[]'),
  PRIMARY KEY (`id`),
  KEY `fms_id` (`fms_id`),
  CONSTRAINT `fms_steps_ibfk_1` FOREIGN KEY (`fms_id`) REFERENCES `fms_managers` (`id`) ON DELETE CASCADE
