--
-- Table structure for table `orders_in_hand`
--

DROP TABLE IF EXISTS `orders_in_hand`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders_in_hand` (
  `id` varchar(36) NOT NULL,
  `order_id` varchar(100) NOT NULL,
  `order_date` date NOT NULL,
  `customer_name` varchar(255) NOT NULL,
  `country` varchar(100) DEFAULT NULL,
  `merchant_name` varchar(255) NOT NULL,
  `marketplace` enum('Etsy','Shopify','Wholesale','Amazon','Website') DEFAULT NULL,
  `po_number` varchar(100) DEFAULT NULL,
  `no_of_products` int DEFAULT NULL,
  `total_qty` int DEFAULT NULL,
  `order_value` decimal(12,2) DEFAULT NULL,
  `currency` enum('USD','GBP','EUR','INR') DEFAULT NULL,
  `payment_status` enum('Paid','Partial','Pending') DEFAULT NULL,
  `production_status` varchar(50) DEFAULT NULL,
  `qc_status` varchar(50) DEFAULT NULL,
  `packing_status` varchar(50) DEFAULT NULL,
  `dispatch_status` enum('Pending','Booked','Dispatched') DEFAULT NULL,
  `expected_dispatch_date` date DEFAULT NULL,
  `expected_delivery` date DEFAULT NULL,
  `priority` enum('Low','Medium','High','Urgent') DEFAULT NULL,
  `delay_days` int DEFAULT NULL,
  `current_stage` varchar(255) DEFAULT NULL,
  `overall_progress` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `erp_number` varchar(255) DEFAULT NULL,
  `ex_factory_date` date DEFAULT NULL,
  `overall_status` varchar(50) DEFAULT 'Under Process',
  `total_cbm` decimal(10,2) DEFAULT '0.00',
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_id` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

